namespace core = "urn:eigenius:core";
namespace patent = "urn:eigenius:demo:patent";
namespace completion = "urn:eigenius:program:components:completion";
namespace request = "urn:eigenius:program:request";

// --- Input type ---

class patent:PatentClaim {
    description = "A patent claim or abstract to be analyzed.";
    requires patent:title, patent:patent_number, patent:abstract_text;
    recommends patent:assignee, patent:filing_date;
}

property patent:title : core:string {
    description = "Title of the patent.";
}

property patent:abstract_text : core:string {
    description = "The abstract or claim text of the patent.";
}

// --- Structured analysis ---

class patent:PatentAnalysis {
    description = "Structured analysis extracted from a patent claim.";
    requires patent:invention_category, patent:technical_domain,
             patent:key_innovations, patent:practical_applications;
}

property patent:key_innovations : core:value_array {
    description = "List of key innovations or novel aspects claimed.";
    element_type = core:string;
}

// --- Pipeline ---

program patent:analyze_patent : patent:PatentClaim -> patent:PatentBrief {
    let analysis : patent:PatentAnalysis = CompleteJson(input) {
        completion:user_prompt = "Analyze this patent and extract structured information.";
        completion:output_schema = patent:PatentAnalysis;
    };
    let summary : core:string = CompleteText(analysis) {
        completion:user_prompt = "Summarise for a non-specialist.";
    };
    Construct patent:PatentBrief {
        patent:summary = summary,
        patent:analysis = analysis
    }
}

// List every Class in the active layer chain — including the patent
// classes loaded by the ESL cell above. Run the ESL cell first; this
// query then surfaces patent:PatentClaim, patent:PatentAnalysis, and
// patent:PatentBrief alongside the core ontology classes.

USING "urn:eigenius:core:Class"

MATCH Class(?c) {
    short_name: ?n
}
RETURN [] {
    name: ?n,
    iri:  ?c
}
ORDER BY ?n

// All resources in the patent namespace, regardless of class.
// `MATCH ?r {}` binds ?r to every resource in scope; the WHERE filters
// by IRI prefix using SQL-style LIKE (% matches any sequence).

MATCH ?r {}
WHERE ?r LIKE "urn:eigenius:demo:patent:%"
RETURN [] {
    iri: ?r
}
ORDER BY ?r

// TypeScript cell — runs in the Phase 4b sandbox (D22 §6.8).
// `eigen` (the SDK) and `previousOutputs` (a map keyed by cell id)
// are in scope. Use `console.log` to surface intermediate values;
// the cell's `return` value is auto-rendered (D22 §6.7).

// 1. Load the patent input inline. (A real notebook would fetch this
//    from a URL; the orchestrator currently doesn't serve static files.)
const transformerPatent = {
  "@id": "urn:eigenius:demo:patent:US10452978B2",
  "urn:eigenius:core:is_a": ["urn:eigenius:demo:patent:PatentClaim"],
  "urn:eigenius:demo:patent:title": "Attention-based sequence transduction neural networks",
  "urn:eigenius:demo:patent:patent_number": "US10452978B2",
  "urn:eigenius:demo:patent:assignee": "Google LLC",
  "urn:eigenius:demo:patent:filing_date": "2018-06-28",
  "urn:eigenius:demo:patent:abstract_text": "Methods, systems, and apparatus for generating an output sequence from an input sequence using attention mechanisms (the Transformer architecture)."
};

const loadResp = await eigen.load(
  JSON.stringify([transformerPatent]),
  { contentType: "application/eigon+json" }
);
console.log(`loaded ${loadResp.resourceCount} resource(s)`);

// 2. Inspect what we just loaded and return it. The auto-renderer
//    dispatches InspectResponse → ResourceInspector.
return await eigen.inspect("urn:eigenius:demo:patent:US10452978B2");
